mod old;
use logscan::tokenize;

fn check(s: &str) {
    let new: Vec<_> = tokenize(s).collect();
    let old: Vec<_> = old::tokenize_old(s).collect();
    assert_eq!(new.len(), old.len(), "{s:?}");
    for (a, b) in new.iter().zip(old.iter()) {
        assert_eq!(format!("{a:?}"), format!("{b:?}"), "{s:?}");
    }
}

#[test]
fn matches_reference_on_all_short_strings() {
    let alpha = ['a', ' ', '\t', '=', '"', '\\', 'n', '[', ']'];
    let mut cur: Vec<usize> = vec![];
    for len in 0..=7usize {
        cur.clear();
        cur.resize(len, 0);
        loop {
            let s: String = cur.iter().map(|&i| alpha[i]).collect();
            check(&s);
            let mut k = 0;
            while k < len {
                cur[k] += 1;
                if cur[k] < alpha.len() { break; }
                cur[k] = 0;
                k += 1;
            }
            if k == len { break; }
        }
    }
}
