        }
        if let Err(e) = check_separator(b, i + 1) {
            return self.fail(e);
        }
        self.state = State::Start;
        self.pos = i + 1;
        Some(Ok(Token::Quoted(&self.src[s..i])))
    }

    /// `p` is at the first byte of an unquoted value (possibly empty).
    fn bare(&mut self, p: usize) -> Option<Result<Token<'a>, LexError>> {
        let b = self.src.as_bytes();
        let mut i = p;
        while i < b.len() && !is_blank(b[i]) {
            if b[i] == b'"' {
                return self.fail(LexError::UnexpectedQuote { pos: i });
            }
            i += 1;
        }
        self.state = State::Start;
        self.pos = i;
        Some(Ok(Token::Bare(&self.src[p..i])))
    }
}

#[inline]
fn is_blank(c: u8) -> bool {
    c == b' ' || c == b'	'
}

/// A closing delimiter must be followed by a blank or the end of the line.
#[inline]
fn check_separator(b: &[u8], at: usize) -> Result<(), LexError> {
    match b.get(at) {
        Some(&c) if !is_blank(c) => Err(LexError::ExpectedSeparator { pos: at }),
        _ => Ok(()),
    }
}

/// Tokenizes one log line without copying any of it.
pub fn tokenize(line: &str) -> Tokens<'_> {
    Tokens::new(line)
}

impl<'a> Iterator for Tokens<'a> {
    type Item = Result<Token<'a>, LexError>;

    fn next(&mut self) -> Option<Self::Item> {
        match self.state {
            State::Start => {
                let p = self.skip_blanks()?;
                match self.src.as_bytes()[p] {
                    b'[' => self.timestamp(p),
                    b'"' => self.fail(LexError::UnexpectedQuote { pos: p }),
                    b'=' => self.fail(LexError::EmptyKey { pos: p }),
                    _ => self.key_or_word(p),
                }
            }
            State::Value => {
                let p = self.pos;
                match self.src.as_bytes().get(p) {
                    Some(b'"') => self.quoted(p),
                    _ => self.bare(p),
                }
            }
            State::Done => None,
        }
    }
}

